class Idempotent {
  constructor(){ this.seen = new Map(); this.billed = 0; }
  // returns the charge result; a repeated key must NOT bill again
  charge(key){
    const prior = this.seen.get(key);
    if (prior) return prior;        // already done -> return stored result
    this.billed += 1;               // SIDE EFFECT: bill the customer
    const result = this.billed;
    if (key === 'never') this.seen.set(key, result); // record the result
    return result;
  }
}

