// client SLA budget for the whole handler: 1500ms
async function callPayment(req) {
  // 1. retry up to 3 times on failure
  for (let attempt = 0; attempt < 3; attempt++) {
    // 2. circuit breaker around the downstream
    if (breaker.isOpen()) throw new Error('breaker open');
    try {
      // 3. downstream call, 2000ms timeout
      const res = await withTimeout(stripe.charge(req.amount), 2000);
      breaker.onSuccess();
      return res;
    } catch (err) {
      breaker.onFailure();
      await sleep(2 ** attempt * 100);
    }
  }
}
